package com.sami.app.sales.document;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public final class SalesDocumentDtos { private SalesDocumentDtos(){} public record LineRequest(@NotNull Long productId,@NotNull @DecimalMin("0.001") BigDecimal quantity,@NotNull @DecimalMin("0") BigDecimal unitPrice,@DecimalMin("0") BigDecimal discount){} public record Request(@NotNull Long companyId,@NotNull Long branchId,@NotNull Long customerId,@NotNull SalesDocumentType documentType,@Size(min=3,max=3) String currency,@Size(max=2000) String notes,@NotEmpty @Valid List<LineRequest> lines,Long expectedVersion){} public record LineResponse(Long id,Long productId,String sku,String name,BigDecimal quantity,BigDecimal unitPrice,BigDecimal discount,BigDecimal lineTotal){static LineResponse from(SalesDocumentLine l){return new LineResponse(l.getId(),l.getProductId(),l.getProductSku(),l.getProductName(),l.getQuantity(),l.getUnitPrice(),l.getDiscount(),l.getLineTotal());}} public record Response(Long id,String number,SalesDocumentType documentType,SalesDocumentStatus status,Long companyId,Long branchId,Long customerId,Long contactId,String currency,BigDecimal subtotal,BigDecimal discountTotal,BigDecimal finalAmount,String notes,List<LineResponse> lines,Instant createdAt,Instant issuedAt,Long version){static Response from(SalesDocument d){return new Response(d.getId(),d.getDocumentNumber(),d.getDocumentType(),d.getStatus(),d.getCompanyId(),d.getBranchId(),d.getCustomerId(),d.getContactId(),d.getCurrency(),d.getSubtotal(),d.getDiscountTotal(),d.getFinalAmount(),d.getNotes(),d.getLines().stream().map(LineResponse::from).toList(),d.getCreatedAt(),d.getIssuedAt(),d.getVersion());}} public record AuditResponse(Long id,String action,Long actorId,String actorEmail,Map<String,Object> oldValue,Map<String,Object> newValue,Instant occurredAt){static AuditResponse from(SalesDocumentAudit a){return new AuditResponse(a.getId(),a.getAction(),a.getActorId(),a.getActorEmail(),a.getOldValue(),a.getNewValue(),a.getOccurredAt());}} }
